			.query()
			.insertInto('email_otps')
			.values({
				_school__id: dbSchool._id,
				email_address: emailAddress,
				otp_hash: otpHash,
				expires_at: new Date(Date.now() + EMAIL_OTP_EXPIRATION_TIME),
			})
